import collections
from typing import Any, Callable, Dict, List

class SagaExecutionError(RuntimeError):
    def __init__(self, step: str, original_error: Exception, compensated_steps: List[str]):
        super().__init__(f"Saga failed at step '{step}': {original_error}")
        self.failed_step = step
        self.original_error = original_error
        self.compensated_steps = compensated_steps

class SagaCoordinator:
    def __init__(self):
        # List of step dictionaries preserving insertion order
        self.steps: List[Dict[str, Any]] = []
        # Execution log for audit/debug purposes
        self.execution_log: List[Dict[str, Any]] = []

    def _validate_step(self, name: Any, action: Any, compensate: Any) -> None:
        """Validate a saga step before registration.

        Args:
            name: Expected to be a non‑empty string.
            action: Callable that performs the step.
            compensate: Callable that undoes the step.
        """
        if not isinstance(name, str) or not name:
            raise ValueError("Step name must be a non‑empty string")
        if not callable(action) or isinstance(action, bool):
            raise ValueError("Action must be a callable (non‑bool)")
        if not callable(compensate) or isinstance(compensate, bool):
            raise ValueError("Compensate must be a callable (non‑bool)")

    def add_step(self, name: Any, action: Any, compensate: Any) -> None:
        """Register a new step in the saga.

        Validation is performed eagerly to avoid corrupt state.
        """
        self._validate_step(name, action, compensate)
        self.steps.append({"name": name, "action": action, "compensate": compensate})

    def _validate_context(self, context: Any) -> None:
        """Validate the execution context supplied to ``execute``.

        The saga expects a mapping (typically a dict) that can be passed to
        step callables. ``None`` or non‑mapping types are rejected.
        """
        if not isinstance(context, collections.abc.Mapping):
            raise ValueError("Execution context must be a mapping (e.g., dict)")

    def execute(self, context: Any) -> Dict[str, Any]:
        """Execute all registered steps sequentially.

        If any step raises an exception, previously successful steps are
        compensated in reverse order. The method then raises a
        ``SagaExecutionError`` containing the failed step name, the original
        exception, and a list of compensated step names.
        """
        self._validate_context(context)
        results: Dict[str, Any] = {}
        executed_steps: List[Dict[str, Any]] = []
        try:
            for step in self.steps:
                # Execute the action; any exception triggers compensation.
                result = step["action"](context)
                results[step["name"]] = result
                executed_steps.append(step)
                # Log successful execution for audit.
                self.execution_log.append({
                    "step": step["name"],
                    "status": "executed",
                    "result": result,
                })
        except Exception as exc:
            # Compensation phase – reverse order of successful steps.
            compensated: List[str] = []
            for completed in reversed(executed_steps):
                try:
                    completed["compensate"](context)
                    compensated.append(completed["name"])
                    self.execution_log.append({
                        "step": completed["name"],
                        "status": "compensated",
                    })
                except Exception as comp_exc:
                    # Compensation failures are logged but do not halt further
                    # compensation; they are surfaced via the original saga error.
                    self.execution_log.append({
                        "step": completed["name"],
                        "status": "compensation_failed",
                        "error": str(comp_exc),
                    })
            # Raise a detailed saga execution error.
            raise SagaExecutionError(step=step["name"], original_error=exc, compensated_steps=compensated) from exc

        return {"success": True, "results": results}
